<"'!doctype html>
<html lang="uk">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Арканоїд</title>
<style>
  *{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;background:radial-gradient(ellipse at top,#18244a,#090d1b 70%);color:#eef4ff;font-family:system-ui,-apple-system,Segoe UI,sans-serif}
  .game{width:min(94vw,840px);padding:22px;border:1px solid #34416b;border-radius:22px;background:#111a32dd;box-shadow:0 24px 80px #0008}
  header{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:14px}h1{font-size:clamp(1.4rem,4vw,2rem);margin:0;letter-spacing:.04em}.stats{display:flex;gap:10px}.stat{background:#202c4d;padding:8px 14px;border-radius:12px;font-weight:700}.stat span{color:#6ee7f9;margin-left:5px}
  canvas{display:block;width:100%;aspect-ratio:800/520;background:linear-gradient(180deg,#0d1730,#101a36);border:1px solid #2b3b65;border-radius:14px;touch-action:none}
  .help{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;color:#aebcdb;font-size:.9rem;margin-top:12px}.help strong{color:#e7edff}.overlay{position:fixed;inset:0;display:grid;place-items:center;background:#050817aa;padding:20px}.panel{max-width:440px;text-align:center;padding:30px;border:1px solid #455789;border-radius:20px;background:#141f3b;box-shadow:0 20px 80px #0009}.panel h2{font-size:2rem;margin:0 0 8px}.panel p{color:#c0cbea;line-height:1.5}.btn{border:0;border-radius:12px;padding:12px 24px;background:linear-gradient(135deg,#6d5dfc,#21c6d7);color:white;font-weight:800;font-size:1rem;cursor:pointer}.btn:hover{filter:brightness(1.12)}
</style>
</head>
<body>
<main class="game">
  <header><h1>✦ АРКАНОЇД</h1><div class="stats"><div class="stat">Рахунок <span id="score">0</span></div><div class="stat">Рівень <span id="level">1 / 2</span></div><div class="stat">Життя <span id="lives">♥♥♥</span></div></div></header>
  <canvas id="board" width="800" height="520" aria-label="Ігрове поле арканоїда"></canvas>
  <div class="help"><span><strong>Керування:</strong> ← → або A / D · рух миші</span><span><strong>Пауза:</strong> пробіл</span></div>
</main>
<div class="overlay" id="overlay"><section class="panel"><h2 id="headline">Арканоїд</h2><p id="message">Відбивай кульку платформою та розбий усі цеглинки. У тебе є 3 життя і 2 рівні!</p><button class="btn" id="start">Почати гру</button></section></div>
<script>
(()=>{
const canvas=document.querySelector('"'#board'),ctx=canvas.getContext('2d'),W=canvas.width,H=canvas.height;
const scoreEl=document.querySelector('#score'),levelEl=document.querySelector('#level'),livesEl=document.querySelector('#lives'),overlay=document.querySelector('#overlay'),headline=document.querySelector('#headline'),message=document.querySelector('#message'),startBtn=document.querySelector('#start');
let score=0,lives=3,level=1,running=false,paused=false,raf=0,keys={};
const paddle={x:W/2-58,y:H-38,w:116,h:13,speed:8};const ball={x:W/2,y:H-58,r:8,vx:3.2,vy:-4.2};let bricks=[];
const palettes=[['#ff657a','#ff9b54','#ffd166','#41d6c3'],['#a78bfa','#ef6aa9','#50c7ff','#69e6ad']];
function buildLevel(){bricks=[];const rows=level===1?4:5,cols=9,bw=72,bh=22,gap=10,left=(W-(cols*bw+(cols-1)*gap))/2,top=65;for(let r=0;r<rows;r++)for(let c=0;c<cols;c++){let hp=level===2&&r<2?2:1;bricks.push({x:left+c*(bw+gap),y:top+r*(bh+9),w:bw,h:bh,hp,max:hp,color:palettes[level-1][r%4],alive:true})}}
function resetBall(){paddle.x=W/2-paddle.w/2;ball.x=W/2;ball.y=H-58;ball.vx=(Math.random()<.5?-1:1)*(level===1?3.2:3.6);ball.vy=-(level===1?4.2:4.6)}
function updateHud(){scoreEl.textContent=score;levelEl.textContent=level+' / 2';livesEl.textContent='♥'.repeat(lives)+'♡'.repeat(3-lives)}
function show(title,text,button='Грати знову'){running=false;cancelAnimationFrame(raf);headline.textContent=title;message.textContent=text;startBtn.textContent=button;overlay.style.display='grid'}
function begin(){if(level>2){score=0;lives=3;level=1;buildLevel()}else if(bricks.length===0)buildLevel();updateHud();overlay.style.display='none';resetBall();running=true;paused=false;loop()}
function rounded(x,y,w,h,r,color){ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
function draw(){ctx.clearRect(0,0,W,H);ctx.save();ctx.globalAlpha=.16;for(let x=30;x<W;x+=40){ctx.fillStyle='#b7ccff';ctx.fillRect(x,0,1,H)}ctx.restore();
 for(const b of bricks)if(b.alive){rounded(b.x,b.y,b.w,b.h,6,b.color);ctx.fillStyle='#ffffff30';ctx.fillRect(b.x+5,b.y+4,b.w-10,3);if(b.hp>1){ctx.fillStyle='#fff';ctx.font='bold 12px system-ui';ctx.textAlign='center';ctx.fillText('◆',b.x+b.w/2,b.y+16)}}
 rounded(paddle.x,paddle.y,paddle.w,paddle.h,7,'#e8f2ff');ctx.fillStyle='#72e6f1';ctx.fillRect(paddle.x+12,paddle.y+3,paddle.w-24,3);
 ctx.beginPath();ctx.arc(ball.x,ball.y,ball.r,0,Math.PI*2);ctx.fillStyle='#fff';ctx.shadowColor='#7deaff';ctx.shadowBlur=18;ctx.fill();ctx.shadowBlur=0;
 }
function loop(){if("'!running)return;if(paused){draw();raf=requestAnimationFrame(loop);return}
 if(keys.ArrowLeft||keys.a||keys.A)paddle.x-=paddle.speed;if(keys.ArrowRight||keys.d||keys.D)paddle.x+=paddle.speed;paddle.x=Math.max(0,Math.min(W-paddle.w,paddle.x));
 ball.x+=ball.vx;ball.y+=ball.vy;if(ball.x-ball.r<0){ball.x=ball.r;ball.vx=Math.abs(ball.vx)}if(ball.x+ball.r>W){ball.x=W-ball.r;ball.vx=-Math.abs(ball.vx)}if(ball.y-ball.r<0){ball.y=ball.r;ball.vy=Math.abs(ball.vy)}
 if(ball.vy>0&&ball.y+ball.r>=paddle.y&&ball.y-ball.r<=paddle.y+paddle.h&&ball.x>=paddle.x&&ball.x<=paddle.x+paddle.w){ball.y=paddle.y-ball.r;const hit=(ball.x-(paddle.x+paddle.w/2))/(paddle.w/2);ball.vx=hit*5.5;ball.vy=-Math.max(3.8,Math.sqrt(36-ball.vx*ball.vx))}
 if(ball.y-ball.r>H){lives--;updateHud();if(!lives){show('"'Ой, гра завершена',"'`Твій рахунок: ${score}. Спробуй ще раз!`,'"'Зіграти знову');return}resetBall()}
 for(const b of bricks)if(b.alive&&ball.x+ball.r>b.x&&ball.x-ball.r<b.x+b.w&&ball.y+ball.r>b.y&&ball.y-ball.r<b.y+b.h){b.hp--;if(b.hp<=0){b.alive=false;score+=10}ball.vy*=-1;updateHud();break}
 if(bricks.every(b=>"'!b.alive)){if(level===1){level=2;buildLevel();updateHud();resetBall()}else{level=3;updateHud();show('"'Перемога"'!'"','Ти розбив усі цеглинки на двох рівнях"'! Фінальний рахунок: '"'+score,'Зіграти знову');return}}
 draw();raf=requestAnimationFrame(loop)}
startBtn.addEventListener('click',begin);canvas.addEventListener('mousemove',e=>{const r=canvas.getBoundingClientRect();paddle.x=(e.clientX-r.left)*W/r.width-paddle.w/2});canvas.addEventListener('touchmove',e=>{e.preventDefault();const r=canvas.getBoundingClientRect();paddle.x=(e.touches[0].clientX-r.left)*W/r.width-paddle.w/2},{passive:false});window.addEventListener('keydown',e=>{keys[e.key]=true;if(e.key===' '&&running){e.preventDefault();paused="'!paused}if(['"'ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault()});window.addEventListener('keyup',e=>keys[e.key]=false);
buildLevel();updateHud();draw();
})();
</script>
</body>
</html>
